import fs from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const tokens = await import(pathToFileURL(path.join(root, "dist/esm/index.js")));

function flat(obj, prefix, out, resolveRef) {
  for (const [key, value] of Object.entries(obj)) {
    const kebab = key.replace(/[A-Z]/g, (m) => "-" + m.toLowerCase());
    const id = prefix ? prefix + "." + kebab : kebab;
    if (typeof value === "object" && value !== null) {
      flat(value, id, out, resolveRef);
    } else {
      out[id] = resolveRef(value);
    }
  }
  return out;
}

function primitivePaths() {
  const map = new Map();
  const walk = (obj, pathParts) => {
    for (const [key, value] of Object.entries(obj)) {
      const kebab = key.replace(/[A-Z]/g, (m) => "-" + m.toLowerCase());
      const parts = [...pathParts, kebab];
      if (typeof value === "object" && value !== null) walk(value, parts);
      else if (typeof value === "string") {
        if (!map.has(value)) map.set(value, "{" + parts.join(".") + "}");
      }
    }
  };
  walk({ color: tokens.colors }, []);
  return map;
}

const refMap = primitivePaths();
const toRef = (v) => (typeof v === "string" && refMap.has(v) ? refMap.get(v) : String(v));

const out = { $schema: "https://design-tokens.org/schema.json" };
const primitives = flat({ color: tokens.colors }, "", {}, (v) => String(v));
const semantics = flat({ semantic: tokens.semantic }, "", {}, toRef);
const components = flat({ component: tokens.componentTokens }, "", {}, toRef);

function nest(target, id, value) {
  const parts = id.split(".");
  let node = target;
  for (let i = 0; i < parts.length - 1; i++) node = node[parts[i]] ??= {};
  // TODO: $type is inferred by a value-shape heuristic, which is not spec-pure —
  // non-color strings (font weights like "600", shadow stacks like focusRing) are
  // misclassified as "dimension". Revisit when the W3C format needs strict typing.
  const type = /^#|^rgba|^transparent|^\{color/.test(String(value)) ? "color" : "dimension";
  node[parts[parts.length - 1]] = { $type: type, $value: value };
}
for (const [id, v] of Object.entries(primitives)) nest(out, id, v);
for (const [id, v] of Object.entries(semantics)) nest(out, id, v);
for (const [id, v] of Object.entries(components)) nest(out, id, v);

fs.writeFileSync(path.join(root, "dist", "tokens.w3c.json"), JSON.stringify(out, null, 2));
console.log("wrote dist/tokens.w3c.json");
